class Cohort:
    def on_can_commit(self, tx):
        if not self.check(tx):
            self.log(tx, "READY-NO")
            return "NO"
        self.acquire_locks(tx)
        self.log_force(tx, "READY-YES")  # force BEFORE reply
        return "YES"

    def on_precommit(self, tx):
        self.log_force(tx, "PREPARED")   # must hit disk first
        return "ACK"

    def on_docommit(self, tx):
        self.commit(tx)                   # make visible
        self.log_force(tx, "COMMITTED")
        self.release_locks(tx)
        return "ACK"

    def on_timeout_waiting_coordinator(self, tx):
        # NEVER decide alone. Elect + poll.
        new_coord = self.elect()          # single driver required
        state = new_coord.poll_all(tx)    # INIT | PREPARED | COMMITTED | ABORTED
        if "COMMITTED" in state:
            return self.on_docommit(tx)
        if "ABORTED" in state:
            return self.on_abort(tx)
        if "PREPARED" in state:
            return self.on_docommit(tx)   # intent was unanimous -> commit
        return self.on_abort(tx)          # nobody prepared -> safe abort
